function getRelevantTabs(query) {
  const q = query.toLowerCase();
  const scores = {
    'Implementation + Dosage': 0,
    'Innovation': 0,
    'Strategic Partnerships': 0,
    'Evidence Adoption': 0
  };
  
  if (/dosage|fidelity|implement|scale|district|barrier|support|infrastructure|coaching|reach/.test(q)) scores['Implementation + Dosage'] += 2;
  if (/innovat|ai|technology|cost.effect|edtech|product|design|tool|platform/.test(q)) scores['Innovation'] += 2;
  if (/partner|distribut|collaboration|ecosystem|sustainability|vendor|commerci/.test(q)) scores['Strategic Partnerships'] += 2;
  if (/evidence|adopt|procure|policy|system|buyer|district decision|purchase/.test(q)) scores['Evidence Adoption'] += 2;
  
  // Default: include top 2 scoring tabs (or all if query is general)
  const sorted = Object.entries(scores).sort((a, b) => b[1] - a[1]);
  const top = sorted.filter(([,s]) => s > 0).slice(0, 2).map(([t]) => t);
  return top.length > 0 ? top : Object.keys(REGISTER);
}

export default async function handler(req) {
  if (req.method === 'OPTIONS') {
    return new Response(null, {
      headers: {
        'Access-Control-Allow-Origin': '*',
        'Access-Control-Allow-Methods': 'POST, OPTIONS',
        'Access-Control-Allow-Headers': 'Content-Type',
      }
    });
  }

  if (req.method !== 'POST') {
    return new Response('Method not allowed', { status: 405 });
  }

  try {
    const body = await req.json();
    const query = body.query || '';
    
    const relevantTabs = getRelevantTabs(query);
    const registerContext = relevantTabs.map(tab => `=== ${tab} ===\n${REGISTER[tab]}`).join('\n\n');

    const systemPrompt = `You are a learning synthesis assistant for the Overdeck Family Foundation (OFF). You have access to the OFF Learning Questions Evidence Register. Below is the relevant evidence data.

EVIDENCE REGISTER:
${registerContext}

When answering a question, respond ONLY with a valid JSON object in this exact format (no markdown, no preamble):
{
  "headline": "One concise sentence directly answering the question, grounded in the register",
  "bullets": [
    {
      "grantee": "Grantee or organization name",
      "portfolio": "Portfolio name",
      "strategy": "Strategy name",
      "snippet": "2-3 sentence summary of the relevant evidence",
      "confidence": "High/Medium/Low/Emerging",
      "tab": "Which register tab this comes from"
    }
  ],
  "limitation": "One sentence on what the evidence does NOT establish or where caution is warranted",
  "source_count": "e.g. 4 evidence rows across 3 sources"
}

Include 2-4 bullets using only evidence from the register above. If the question cannot be answered from the register, return {"headline": "The register does not contain evidence directly relevant to this question.", "bullets": [], "limitation": "", "source_count": "0 evidence rows"}`;

    const response = await fetch('https://api.anthropic.com/v1/messages', {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'x-api-key': process.env.ANTHROPIC_API_KEY,
        'anthropic-version': '2023-06-01'
      },
      body: JSON.stringify({
        model: 'claude-sonnet-4-5',
        max_tokens: 1000,
        system: systemPrompt,
        messages: [{ role: 'user', content: query }]
      })
    });

    if (!response.ok) {
      const errText = await response.text();
      return new Response(JSON.stringify({ error: 'Anthropic error ' + response.status, detail: errText }), {
        status: 500,
        headers: { 'Content-Type': 'application/json', 'Access-Control-Allow-Origin': '*' }
      });
    }

    const data = await response.json();
    return new Response(JSON.stringify(data), {
      headers: { 'Content-Type': 'application/json', 'Access-Control-Allow-Origin': '*' }
    });
  } catch (err) {
    return new Response(JSON.stringify({ error: err.message }), {
      status: 500,
      headers: { 'Content-Type': 'application/json', 'Access-Control-Allow-Origin': '*' }
    });
  }
}
